draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2 - 50 + 20*Math.sin(t), 30, 0, 2*Math.PI);
  ctx.stroke();

  // question mark
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.cos(t), H/2 - 50 + 20*Math.sin(t));
  ctx.lineTo(W/2 + 50 + 20*Math.cos(t) + 10, H/2 - 50 + 20*Math.sin(t) + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t) + 5, H/2 - 50 + 20*Math.sin(t) + 30, 5, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
